@push('scripts')
<script>
$(function(){
    function itemSelect($el){window.erpInitSelect2($el,{placeholder:'ค้นหาสินค้า',allowClear:true,ajax:{url:$el.data('url'),delay:250,data:function(p){return {q:p.term||'',page:p.page||1};},processResults:function(data){return data;}}});}
    function wire($row){var $select=$row.find('.js-component');itemSelect($select);$select.on('select2:select',function(e){$row.find('.js-uom-id').val(e.params.data.uom_id);$row.find('.js-uom-label').text(e.params.data.uom_label||'-');}).on('select2:clear',function(){$row.find('.js-uom-id').val('');$row.find('.js-uom-label').text('-');});$row.find('.js-substitute-item').each(function(){wireSubstitute($(this));});}
    function wireSubstitute($select){itemSelect($select);$select.on('select2:select',function(e){$select.closest('.js-substitute').find('[name$="[uom_id]"]').val(e.params.data.uom_id);});}
    function addSubstitute($row){var line=$row.find('.js-component').attr('name').match(/lines\[([^\]]+)\]/)[1],i=Date.now(),html='<div class="bom-substitute-row js-substitute"><div class="flex-grow-1"><select class="form-select js-substitute-item" name="lines['+line+'][substitutes]['+i+'][substitute_item_id]" data-url="{{ route('production.boms.item-options') }}"><option value="">ค้นหาวัตถุดิบทดแทน</option></select></div><div class="bom-factor"><input class="form-control text-end" type="number" min="0.00000001" step="any" name="lines['+line+'][substitutes]['+i+'][quantity_factor]" value="1" title="ตัวคูณจำนวน"></div><input type="hidden" name="lines['+line+'][substitutes]['+i+'][uom_id]"><input type="hidden" name="lines['+line+'][substitutes]['+i+'][priority]" value="'+(i)+'"><button class="btn btn-app-danger js-remove-substitute" type="button" title="ลบวัตถุดิบทดแทน" aria-label="ลบวัตถุดิบทดแทน"><i class="bx bx-trash" aria-hidden="true"></i></button></div>';$row.find('.js-substitutes').append(html);wireSubstitute($row.find('.js-substitute-item').last());}
    $('#bom-lines .bom-line').each(function(){wire($(this));});
    var $finished=$('#finished-item');if($finished.length){itemSelect($finished);$finished.on('select2:select',function(e){$('#finished-uom-id').val(e.params.data.uom_id);$('#finished-uom-label').text('หน่วยฐาน: '+(e.params.data.uom_label||'-'));}).on('select2:clear',function(){$('#finished-uom-id').val('');$('#finished-uom-label').text('เลือกสินค้าเพื่อกำหนดหน่วยฐาน');});}
    $('#add-bom-operation').on('click',function(){var i=$('#bom-operations .bom-operation').length,html='<div class="row g-2 mb-2 bom-operation"><div class="col-1"><span class="form-control-plaintext text-center">'+(i+1)+'</span></div><div class="col-7"><input class="form-control" name="operations['+i+'][name]" maxlength="150" required placeholder="ชื่อขั้นตอน"></div><div class="col-3"><input class="form-control" type="number" min="1" name="operations['+i+'][planned_minutes]" placeholder="นาที"></div><div class="col-1"><button class="btn btn-sm btn-app-danger js-remove-operation" type="button" title="ลบขั้นตอน" aria-label="ลบขั้นตอน"><i class="bx bx-trash" aria-hidden="true"></i></button></div></div>';$('#bom-operations').append(html);});
    $(document).on('click','.js-remove-operation',function(){$(this).closest('.bom-operation').remove();$('#bom-operations .bom-operation').each(function(i){$(this).find('.form-control-plaintext').text(i+1);$(this).find('input').each(function(){var n=$(this).attr('name');$(this).attr('name',n.replace(/operations\[\d+\]/,'operations['+i+']'));});});});
    $('#add-bom-line').on('click',function(){var i=Date.now(),$row=$($('#bom-line-template').html().replaceAll('__INDEX__',i));$('#bom-lines').append($row);wire($row);});
    $(document).on('click','.js-add-substitute',function(){addSubstitute($(this).closest('.bom-line'));});
    $(document).on('click','.js-remove-substitute',function(){$(this).closest('.js-substitute').remove();});
    $(document).on('click','.js-remove-line',function(){if($('#bom-lines .bom-line').length>1){$(this).closest('.bom-line-card').remove();$('#bom-lines .bom-line-card').each(function(i){$(this).find('.bom-line-number').text(i+1);});}});
    window.erpAjaxForm({form:'#bom-form',redirect:true});
});
</script>
@endpush
